import { Chess } from './src/chess'

function attempt(label: string, fn: () => unknown) {
  try {
    console.log(`OK   ${label}:`, JSON.stringify(fn()))
  } catch (e) {
    console.log(`FAIL ${label}: ${e instanceof Error ? e.message : e}`)
  }
}

// Black pawns on rank 1 (their back rank), black to move — mirror image of the reported white/rank-8 bug.
// A white pawn sits on the target square; put() replaces it with a black pawn.
const setups: Array<[string, string]> = [
  ['a1', 'rnbqkbnr/pppppppp/8/8/8/8/1PPPPPPP/RNBQKBNR b KQkq - 0 1'],
  ['e1', 'rnbqkbnr/pppppppp/8/8/8/8/4P3/RNBQKBNR b KQkq - 0 1'],
  ['h1', 'rnbqkbnr/pppppppp/8/8/8/8/PPPPPPP1/RNBQKBNR b KQkq - 0 1'],
]

for (const [sq, fen] of setups) {
  const c = new Chess(fen)
  c.put({ type: 'p', color: 'b' } as never, sq)
  attempt(`black pawn ${sq}, moves({square:${sq}, verbose:true})`, () =>
    c.moves({ square: sq as never, verbose: true }),
  )
}

// Black pawn on rank 1 must not add moves to the full move list.
attempt('black pawn e1, full moves count (expect 20)', () => {
  const c = new Chess(setups[1][1])
  c.put({ type: 'p', color: 'b' } as never, 'e1')
  return c.moves().length
})

// Reported white/rank-8 case still fixed (sanity).
attempt('white pawn h8, moves({square:h8, verbose:true})', () => {
  const c = new Chess()
  c.put({ type: 'p', color: 'w' } as never, 'h8')
  return c.moves({ square: 'h8' as never, verbose: true })
})

